<script setup lang="ts">
/**
 * A verification-code field drawn as separate digit cells (`design/components/otp-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/otp-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef } from 'vue'

import { agentMember } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/otp-input.module.css'

export type OTPLength = NonNullable<OTPInputProps['length']>

export interface OTPInputProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  /**
   * Usually set by FormField, for example for "That code didn't match".
   */
  invalid?: boolean
  /**
   * The code length, 4 or 6, which are the lengths real code systems use.
   */
  length?: 4 | 6
  /**
   * Set directly on the real input, so no hidden input is needed.
   */
  name?: string
  /**
   * Digits only. Every write path filters and truncates to `length`.
   */
  value?: string
}

defineOptions({ name: 'OTPInput', inheritAttrs: false, controlKind: 'field' })

const props = withDefaults(defineProps<OTPInputProps>(), {
  ariaRequired: undefined,
  disabled: false,
  invalid: false,
  length: 6,
})
const emit = defineEmits<{ change: [value: string]; complete: [code: string] }>()
const uncontrolled = ref((props.defaultValue ?? '').replace(/\D/g, '').slice(0, props.length))
const focused = ref(false)
const field = useTemplateRef<HTMLElement>('field')
const code = computed(() =>
  (props.value ?? uncontrolled.value).replace(/\D/g, '').slice(0, props.length),
)
const caretIndex = computed(() =>
  code.value.length === props.length ? props.length - 1 : code.value.length,
)
const cells = computed(() => Array.from({ length: props.length }, (_, index) => index))
const commit = computed(
  () => (next: string) =>
    ((before: string) => (
      (uncontrolled.value = next),
      next !== before && emit('change', next),
      next.length === props.length && before.length < props.length && emit('complete', next)
    ))(code.value),
)
const receive = computed(
  () => (event: Event) =>
    ((input: HTMLInputElement) => (
      commit.value(input.value.replace(/\D/g, '').slice(0, props.length)),
      (input.value = code.value)
    ))(event.target as HTMLInputElement),
)
const receivePaste = computed(
  () => (event: ClipboardEvent) => (
    event.preventDefault(),
    commit.value(
      (event.clipboardData?.getData('text') ?? '').replace(/\D/g, '').slice(0, props.length),
    ),
    ((event.target as HTMLInputElement).value = code.value)
  ),
)
const pinCaret = computed(
  () => (event: Event) =>
    ((node: HTMLInputElement) =>
      (node.selectionStart !== code.value.length || node.selectionEnd !== code.value.length) &&
      node.setSelectionRange(code.value.length, code.value.length))(
      event.currentTarget as HTMLInputElement,
    ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'OTPInput',
    element: () => field.value,
    state: () => ({ value: code.value, disabled: props.disabled, invalid: props.invalid }),
    actions: {},
    secret: ['value'],
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    :class="styles.root"
    :data-invalid="invalid ? '' : undefined"
    :data-disabled="disabled ? '' : undefined"
    data-member="otp-input"
  >
    <!-- field -->
    <input
      ref="field"
      :class="styles.input"
      type="text"
      :value="code"
      :disabled="disabled"
      :name="name"
      :id="id"
      inputmode="numeric"
      autocomplete="one-time-code"
      spellcheck="false"
      autocapitalize="off"
      autocorrect="off"
      :maxlength="length"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :aria-required="ariaRequired"
      :aria-invalid="invalid ? true : undefined"
      @input="receive($event)"
      @paste="receivePaste($event)"
      @keydown="
        ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes($event.key) &&
        $event.preventDefault()
      "
      @select="pinCaret($event)"
      @mouseup="pinCaret($event)"
      @keyup="pinCaret($event)"
      @focus="((focused = true), pinCaret($event))"
      @blur="focused = false"
    />
    <template v-for="index in cells" :key="index">
      <!-- cell -->
      <span
        :class="styles.cell"
        aria-hidden="true"
        :data-filled="code[index] !== undefined ? '' : undefined"
        :data-caret="focused && index === caretIndex ? '' : undefined"
      >
        <template v-if="code[index] !== undefined">
          <template v-for="digit in [code[index]]" :key="`${index}-${digit}`">
            <span :class="styles.digit">
              {{ digit }}
            </span>
          </template>
        </template>
      </span>
    </template>
  </div>
</template>
